"use client";
import React from "react";
import { motion } from "framer-motion";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="relative w-full max-w-5xl mx-auto px-4">
      <div className="relative flex items-center justify-center" style={{ height: "360px" }}>
        {cards.map((card, index) => {
          // Left, Center, Right positions with maximum spacing
          const xOffset = (index - 1) * 400; // -400, 0, 400
          const rotate = 0; // 0 degrees - straight cards

          return (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: index * 0.15, ease: [0.25, 0.46, 0.45, 0.94] }}
              whileHover={{
                y: -60,
                transition: { duration: 0.4, ease: "easeOut" }
              }}
              className="absolute cursor-pointer"
              style={{
                x: `${xOffset}px`,
                rotate: `${rotate}deg`,
                zIndex: cards.length - Math.abs(index - 1),
              }}
            >
              {/* Card Container - Dark elegant design */}
              <div
                className="relative overflow-hidden rounded-3xl"
                style={{
                  width: "300px",
                  background: "linear-gradient(145deg, #1a1510 0%, #0f0a08 100%)",
                  border: "1px solid rgba(212, 175, 55, 0.3)",
                  boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
                }}
              >
                {/* Top accent bar */}
                <div
                  className="absolute top-0 left-0 right-0 h-1"
                  style={{ background: "linear-gradient(90deg, #d4af37, #f4d77a, #d4af37)" }}
                />

                {/* Card Content */}
                <div className="relative z-10 p-6">
                  {/* Icon */}
                  <div
                    className="w-10 h-10 rounded-lg flex items-center justify-center mb-4"
                    style={{
                      background: "rgba(212, 175, 55, 0.15)",
                      color: "#d4af37",
                    }}
                  >
                    {card.icon}
                  </div>

                  {/* Badge */}
                  <div className="mb-3">
                    <span
                      className="inline-block text-xs font-bold uppercase tracking-wider px-3 py-1 rounded-md"
                      style={{
                        background: "rgba(212, 175, 55, 0.15)",
                        color: "#d4af37",
                      }}
                    >
                      {card.badge}
                    </span>
                  </div>

                  {/* Title */}
                  <h3 className="text-xl font-bold mb-2" style={{ fontFamily: "Outfit, sans-serif", color: "#ffffff" }}>
                    {card.title}
                  </h3>

                  {/* Description */}
                  <p className="text-sm leading-relaxed mb-3 font-medium" style={{ color: "rgba(255,255,255,0.75)" }}>
                    {card.description}
                  </p>

                  {/* Date */}
                  <p className="text-xs font-medium" style={{ color: "rgba(255,255,255,0.5)" }}>
                    {card.date}
                  </p>
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default DisplayCards;
